"use client";

import * as React from "react";
import { useMorph } from "@/lib/cojeev-motion/use-morph";
import { cva, type VariantProps } from "class-variance-authority";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Icon } from "@/components/ui/icon";
import * as Primitive from "@radix-ui/react-toast";
import { useFlowAppearance } from "@/lib/cojeev-motion/use-flow";
export const toastVariants = cva(
  "v-toast [display:flex] [align-items:center] [gap:var(--s-3)] [padding:var(--s-3)_var(--s-4)] [border-radius:var(--r-card-sm)] [background:var(--v-ink)] [color:var(--v-on-ink)] [font-size:var(--fs-control)]",
  {
    variants: { variant: { default: "", cream: "-cream", danger: "-danger" } },
    defaultVariants: { variant: "default" },
  },
);
export type ToastProviderProps = React.ComponentProps<
  typeof Primitive.Provider
>;
export function ToastProvider(props: ToastProviderProps) {
  return <Primitive.Provider duration={5000} {...props} />;
}
export type ToastViewportProps = React.ComponentProps<
  typeof Primitive.Viewport
>;
export function ToastViewport({ className, ...props }: ToastViewportProps) {
  return (
    <Primitive.Viewport
      data-slot="toast-viewport"
      data-part="viewport"
      className={cn(
        "v-toaster fixed right-[var(--s-6)] bottom-[var(--s-6)] grid gap-[var(--s-2)] z-[var(--z-toast)] w-[min(380px,calc(100%-48px))]",
        className,
      )}
      {...props}
    />
  );
}
export type ToastProps = React.ComponentProps<typeof Primitive.Root> &
  VariantProps<typeof toastVariants> & {
    durable?: boolean;
    appearance?: "compact" | "actionable" | "receipt";
  };
export function Toast({
  className,
  variant,
  appearance,
  durable,
  duration,
  ref,
  ...props
}: ToastProps) {
  const morphRef = useMorph<HTMLLIElement>("surfaces", ref);
  const flowRef = useFlowAppearance<HTMLLIElement>(
    props.open ?? true,
    morphRef,
    "enter",
  );
  return (
    <Primitive.Root
      ref={flowRef}
      data-slot="toast"
      data-part="root"
      data-appearance={appearance}
      duration={durable ? Infinity : duration}
      className={cn(toastVariants({ variant }), className)}
      {...props}
    />
  );
}
export type ToastTitleProps = React.ComponentProps<typeof Primitive.Title>;
export function ToastTitle({ className, ...props }: ToastTitleProps) {
  return (
    <Primitive.Title
      data-slot="toast-title"
      data-part="title"
      className={cn("font-medium", className)}
      {...props}
    />
  );
}
export type ToastDescriptionProps = React.ComponentProps<
  typeof Primitive.Description
>;
export function ToastDescription({
  className,
  ...props
}: ToastDescriptionProps) {
  return (
    <Primitive.Description
      data-slot="toast-description"
      data-part="description"
      className={cn("flex-1", className)}
      {...props}
    />
  );
}
export type ToastActionProps = React.ComponentProps<typeof Primitive.Action>;
export function ToastAction({
  className,
  asChild,
  children,
  ...props
}: ToastActionProps) {
  return (
    <Primitive.Action
      data-slot="toast-action"
      data-part="action"
      className={className}
      asChild
      {...props}
    >
      {asChild ? (
        children
      ) : (
        <Button size="sm" variant="outline">
          {children}
        </Button>
      )}
    </Primitive.Action>
  );
}

export type ToastCloseProps = React.ComponentProps<typeof Primitive.Close>;
export function ToastClose({
  className,
  children,
  asChild,
  ...props
}: ToastCloseProps) {
  return (
    <Primitive.Close
      data-slot="toast-close"
      data-part="close"
      aria-label="Dismiss"
      className={className}
      asChild
      {...props}
    >
      {asChild ? (
        children
      ) : (
        <Button
          variant="ghost"
          style={{ minWidth: 44, minHeight: 44, padding: 0 }}
        >
          {children ?? <Icon name="x" size="sm" aria-hidden="true" />}
        </Button>
      )}
    </Primitive.Close>
  );
}

export function ToastIndicator({
  className,
  ...props
}: React.ComponentProps<"span">) {
  return (
    <span
      data-slot="toast-indicator"
      aria-hidden="true"
      className={cn("v-toast__indicator", className)}
      {...props}
    >
      <Icon name="check" size="sm" />
    </span>
  );
}

@layer cojeev-states {
/* Cojeev authored subparts, state precedence, and irreducible shapes; scoped to this registry item. */
.v-toast:where([data-slot="toast"], [data-slot^="toast-"]).-danger {
  color: var(--destructive-foreground);
}
.v-toaster:where([data-slot="toast"], [data-slot^="toast-"]) {
  position: fixed;
  right: var(--s-6);
  bottom: var(--s-6);
  display: grid;
  gap: var(--s-2);
  z-index: var(--z-toast);
  width: min(380px, calc(100% - 48px));
}
.v-toast:where([data-slot="toast"], [data-slot^="toast-"]) {
  animation: v-toast-in var(--t-max) var(--enter);
}
.v-toast:where([data-slot="toast"], [data-slot^="toast-"]).-cream {
  background: var(--v-canvas);
  color: var(--v-text);
  border: 1px solid var(--v-border);
}
.v-toast:where([data-slot="toast"], [data-slot^="toast-"]).-danger {
  background: var(--v-danger-fill);
  color: var(--destructive-foreground);
}
.v-toast:where([data-slot="toast"], [data-slot^="toast-"]) .v-btn {
  height: 30px;
  padding: 0 12px;
  font-size: 12px;
  margin-left: auto;
  background: rgba(251, 244, 230, 0.14);
  color: inherit;
}
.v-toast:where([data-slot="toast"], [data-slot^="toast-"]).-cream .v-btn {
  background: var(--v-beige);
}
.v-toast:where([data-slot="toast"], [data-slot^="toast-"]).-out {
  animation: v-toast-out var(--t-element) var(--exit) forwards;
}
@keyframes v-toast-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
}
@keyframes v-toast-out {
  to {
    opacity: 0;
    transform: translateY(8px);
  }
}
@media (prefers-reduced-motion: reduce) {
  [data-slot="toast"],
  [data-slot^="toast-"],
  [data-slot="toast"]::before,
  [data-slot="toast"]::after,
  [data-slot^="toast-"]::before,
  [data-slot^="toast-"]::after {
    animation-duration: 0s;
    animation-iteration-count: 1;
    transition-duration: 0s;
    scroll-behavior: auto;
  }
}

[data-slot="toast"][data-state="closed"] {
  animation: v-toast-out var(--t-element) var(--exit) forwards;
}
[data-slot="toast"][data-swipe="move"] {
  transform: translateX(var(--radix-toast-swipe-move-x));
}
[data-slot="toast"][data-swipe="end"] {
  transform: translateX(var(--radix-toast-swipe-end-x));
  opacity: 0;
}
[data-slot="toast"] {
  min-width: 0;
  flex-wrap: wrap;
  overflow-wrap: anywhere;
}
[data-slot="toast-title"],
[data-slot="toast-description"] {
  min-width: 0;
}
[data-slot="toast-action"],
[data-slot="toast-close"] {
  flex-shrink: 0;
}

/* Explicit hierarchy; title and description no longer compete in one flex row. */
.v-toast[data-appearance] {
  display: grid;
  grid-template-columns: 36px minmax(0, 1fr) 44px;
  grid-template-areas: "icon title close" "icon description close" ". action .";
  align-items: center;
  column-gap: 12px;
  row-gap: 6px;
  width: 100%;
  padding: 16px;
  border-radius: 20px;
  background: var(--card);
  color: var(--v-text);
  border: 1px solid var(--v-border);
}
.v-toast[data-appearance] [data-slot="toast-title"] {
  grid-area: title;
  font-size: 15px;
  font-weight: 600;
  line-height: 1.35;
}
.v-toast[data-appearance] [data-slot="toast-description"] {
  grid-area: description;
  font-size: 13px;
  color: var(--toast-secondary, var(--v-text-2));
  line-height: 1.6;
}
.v-toast[data-appearance] [data-slot="toast-indicator"] {
  grid-area: icon;
  align-self: start;
  display: grid;
  place-items: center;
  width: 36px;
  height: 36px;
  border-radius: 42% 58% 52% 48%;
  background: var(--v-olive);
  color: var(--v-on-accent);
}
:root .v-toast[data-appearance] .v-btn[data-slot="toast-action"] {
  grid-area: action;
  justify-self: start;
  margin: 6px 0 0;
  min-height: 44px;
  background: var(--v-blue);
  color: var(--v-on-accent);
  padding-inline: 18px;
  font-size: 13px;
}
:root .v-toast[data-appearance] .v-btn[data-slot="toast-close"] {
  grid-area: close;
  align-self: start;
  margin: 0;
  width: 44px;
  height: 44px;
  background: transparent;
  color: inherit;
}
.v-toast[data-appearance]:not(.-cream):not(.-danger) {
  background: var(--v-ink);
  color: var(--v-on-ink);
  --toast-primary: var(--v-on-ink);
  --toast-secondary: var(--v-on-ink);
}
.v-toast[data-appearance].-danger {
  background: var(--v-danger-fill);
  color: var(--destructive-foreground);
  --toast-primary: var(--destructive-foreground);
  --toast-secondary: var(--destructive-foreground);
}
.v-toast[data-appearance="compact"] {
  grid-template-areas: "icon title close";
  padding: 10px 12px;
  border-radius: 999px;
}
.v-toast[data-appearance="compact"] [data-slot="toast-indicator"] {
  align-self: center;
}
.v-toast[data-appearance="receipt"] {
  grid-template-areas: "icon title close" "icon description close" "receipt receipt receipt";
  padding: 20px;
  border-radius: 20px 20px 8px 8px;
}
.v-toast__receipt {
  grid-area: receipt;
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  padding-top: 16px;
  margin-top: 12px;
  border-top: 1px dashed var(--v-border);
  font-size: 11px;
  color: var(--toast-secondary, var(--v-text-2));
}
.v-toast__receipt > span {
  display: grid;
  gap: 6px;
}
.v-toast__receipt strong {
  font-size: 12px;
  font-weight: 500;
  color: var(--toast-primary, var(--v-text));
}
.v-toast-demo {
  width: 100%;
  display: grid;
  justify-items: start;
  gap: 16px;
}
.v-toast-demo__status {
  font-size: 13px;
  color: var(--v-text-2);
}
.v-toast-demo .v-toast-demo__viewport {
  position: static;
  width: min(100%, 440px);
  margin: 0;
  padding: 0;
  justify-self: end;
  list-style: none;
  outline: none;
}
.v-toast-demo .v-toast-demo__viewport:empty {
  display: none;
}
.v-toast[data-flow-presence][data-state="open"] {
  animation: none;
}
.v-toast[data-flow-presence][data-state="closed"] {
  animation: v-toast-retain var(--flow-exit-duration, 0.22s) linear;
}
@keyframes v-toast-retain {
  from {
    visibility: visible;
  }
  to {
    visibility: visible;
  }
}
@media (prefers-reduced-motion: reduce) {
  .v-toast[data-flow-presence][data-state="closed"] {
    animation: none;
  }
}

}
